-1. พื้นฐานการดึงข้อมูล
ใช้ `SELECT` ดึงข้อมูล, `WHERE` กรอง, `ORDER BY` เรียงลำดับ
```sql
-- SELECT: ดึงเฉพาะคอลัมน์ที่ต้องการ
SELECT CustomerName, City FROM Customers;

-- DISTINCT: ดูรายชื่อประเทศแบบไม่ซ้ำ
SELECT DISTINCT Country FROM Customers;

-- WHERE: กรองเฉพาะลูกค้าในไทย
SELECT * FROM Customers WHERE Country = 'Thailand';

-- ORDER BY: เรียงชื่อจาก A-Z (DESC = Z-A)
SELECT * FROM Customers ORDER BY CustomerName ASC;

-- AND / OR / NOT
SELECT * FROM Customers WHERE Country = 'Thailand' AND City = 'Bangkok';
SELECT * FROM Customers WHERE City = 'Bangkok' OR City = 'Chiang Mai';
SELECT * FROM Customers WHERE NOT Country = 'Thailand';
```
-2. จัดการข้อมูล
เพิ่ม แก้ไข ลบข้อมูล และตรวจค่า NULL ข้อควรระวัง: `UPDATE` และ `DELETE` ที่ไม่มี `WHERE` จะมีผลกับทุกแถว
```sql
-- INSERT: เพิ่มลูกค้าใหม่
INSERT INTO Customers (CustomerName, City, Country)
VALUES ('Somchai Shop', 'Bangkok', 'Thailand');

-- UPDATE: แก้ไขเมือง
UPDATE Customers SET City = 'Nonthaburi' WHERE CustomerID = 1;

-- DELETE: ลบลูกค้า
DELETE FROM Customers WHERE CustomerID = 1;

-- NULL: หาลูกค้าที่ยังไม่ระบุเมือง
SELECT * FROM Customers WHERE City IS NULL;
SELECT * FROM Customers WHERE City IS NOT NULL;
```
- 3. ฟังก์ชันสรุปผล (Aggregate Functions)
`GROUP BY` จัดกลุ่มข้อมูล ส่วน `HAVING` ใช้กรองหลังจัดกลุ่ม (ต่างจาก `WHERE` ที่กรองก่อน)
```sql
-- COUNT / SUM / AVG / MIN / MAX
SELECT COUNT(*)    AS TotalOrders FROM Orders;
SELECT SUM(Amount) AS TotalSales  FROM Orders;
SELECT AVG(Amount) AS AvgSales    FROM Orders;
SELECT MIN(Amount) AS MinOrder, MAX(Amount) AS MaxOrder FROM Orders;

-- GROUP BY: นับจำนวนลูกค้าแยกตามประเทศ
SELECT Country, COUNT(*) AS NumCustomers
FROM Customers
GROUP BY Country;

-- HAVING: เฉพาะประเทศที่มีลูกค้าเกิน 5 ราย
SELECT Country, COUNT(*) AS NumCustomers
FROM Customers
GROUP BY Country
HAVING COUNT(*) > 5;
```
- 4. ค้นหาแบบยืดหยุ่น
Wildcard: `%` = กี่ตัวอักษรก็ได้, `_` = 1 ตัวอักษร
```sql
-- LIKE + Wildcards
SELECT * FROM Customers WHERE CustomerName LIKE 'S%';     -- ขึ้นต้นด้วย S
SELECT * FROM Customers WHERE CustomerName LIKE '%Shop%'; -- มีคำว่า Shop
SELECT * FROM Customers WHERE City LIKE '_angkok';        -- ตัวแรกเป็นอะไรก็ได้

-- IN: ตรงกับค่าใดค่าหนึ่งในรายการ
SELECT * FROM Customers WHERE Country IN ('Thailand', 'Japan', 'Vietnam');

-- BETWEEN: อยู่ในช่วง (รวมค่าขอบ)
SELECT * FROM Orders WHERE Amount BETWEEN 1000 AND 5000;
SELECT * FROM Orders WHERE OrderDate BETWEEN '2026-01-01' AND '2026-06-30';
```
- 5. เชื่อมตาราง (JOIN)
ชนิด	ผลลัพธ์
INNER JOIN	เฉพาะแถวที่ตรงกันทั้งสองตาราง
LEFT JOIN	ทุกแถวจากตารางซ้าย + แถวที่ตรงกันจากตารางขวา
RIGHT JOIN	ทุกแถวจากตารางขวา + แถวที่ตรงกันจากตารางซ้าย
FULL JOIN	ทุกแถวจากทั้งสองตาราง
SELF JOIN	เชื่อมตารางกับตัวเอง
```sql
-- INNER JOIN: เฉพาะลูกค้าที่มีออเดอร์
SELECT c.CustomerName, o.OrderID, o.Amount
FROM Customers c
INNER JOIN Orders o ON c.CustomerID = o.CustomerID;

-- LEFT JOIN: ลูกค้าทุกคน แม้ยังไม่เคยสั่ง (Order จะเป็น NULL)
SELECT c.CustomerName, o.OrderID
FROM Customers c
LEFT JOIN Orders o ON c.CustomerID = o.CustomerID;

-- RIGHT JOIN: ออเดอร์ทุกรายการ แม้ไม่พบข้อมูลลูกค้า
SELECT c.CustomerName, o.OrderID
FROM Customers c
RIGHT JOIN Orders o ON c.CustomerID = o.CustomerID;

-- FULL JOIN: ทุกแถวจากทั้งสองตาราง
SELECT c.CustomerName, o.OrderID
FROM Customers c
FULL OUTER JOIN Orders o ON c.CustomerID = o.CustomerID;

-- SELF JOIN: จับคู่ลูกค้าที่อยู่เมืองเดียวกัน
SELECT a.CustomerName AS Customer1, b.CustomerName AS Customer2, a.City
FROM Customers a
JOIN Customers b ON a.City = b.City AND a.CustomerID <> b.CustomerID;

-- UNION: รวมผลลัพธ์ (ตัดแถวซ้ำ) / UNION ALL: รวมทั้งหมดรวมแถวซ้ำ
SELECT City FROM Customers
UNION
SELECT City FROM Suppliers;
```
-6. ขั้นสูง
```sql
-- CASE: แบ่งระดับออเดอร์ตามยอดเงิน
SELECT OrderID, Amount,
  CASE
    WHEN Amount >= 10000 THEN 'High'
    WHEN Amount >= 3000  THEN 'Medium'
    ELSE 'Low'
  END AS OrderLevel
FROM Orders;

-- EXISTS: ลูกค้าที่มีออเดอร์อย่างน้อย 1 รายการ
SELECT CustomerName FROM Customers c
WHERE EXISTS (SELECT 1 FROM Orders o WHERE o.CustomerID = c.CustomerID);

-- ANY: มากกว่าอย่างน้อย 1 ค่า / ALL: มากกว่าทุกค่า
SELECT * FROM Orders
WHERE Amount > ANY (SELECT Amount FROM Orders WHERE CustomerID = 5);
SELECT * FROM Orders
WHERE Amount > ALL (SELECT Amount FROM Orders WHERE CustomerID = 5);

-- Stored Procedure (SQL Server)
CREATE PROCEDURE GetCustomersByCountry @Country NVARCHAR(50)
AS
  SELECT * FROM Customers WHERE Country = @Country;
GO
EXEC GetCustomersByCountry @Country = 'Thailand';
```
-7. ออกแบบฐานข้อมูล
```sql
-- CREATE TABLE + Primary Key + Constraints
CREATE TABLE Customers (
  CustomerID   INT PRIMARY KEY IDENTITY(1,1),   -- Auto Increment (SQL Server)
  CustomerName NVARCHAR(100) NOT NULL,
  Email        NVARCHAR(100) UNIQUE,
  City         NVARCHAR(50) DEFAULT 'Bangkok',
  Country      NVARCHAR(50)
);

-- Foreign Key + CHECK
CREATE TABLE Orders (
  OrderID    INT PRIMARY KEY IDENTITY(1,1),
  CustomerID INT FOREIGN KEY REFERENCES Customers(CustomerID),
  OrderDate  DATE,
  Amount     DECIMAL(10,2) CHECK (Amount > 0)
);

-- ALTER TABLE: เพิ่ม / ลบคอลัมน์
ALTER TABLE Customers ADD Phone NVARCHAR(20);
ALTER TABLE Customers DROP COLUMN Phone;

-- INDEX: ช่วยให้ค้นหาเร็วขึ้น
CREATE INDEX idx_customer_city ON Customers (City);

-- VIEW: ตารางเสมือนจาก Query ที่ใช้บ่อย
CREATE VIEW ThaiCustomers AS
SELECT CustomerName, City FROM Customers WHERE Country = 'Thailand';

SELECT * FROM ThaiCustomers;

-- DROP TABLE: ลบทั้งตาราง (ข้อมูลหายถาวร ควรแบ็กอัปก่อน)
DROP TABLE Orders;
```
-8. ความปลอดภัย: SQL Injection
SQL Injection เกิดเมื่อนำ input ของผู้ใช้ไปต่อเป็นคำสั่ง SQL ตรง ๆ ผู้โจมตีจึงแทรกคำสั่งเพื่อดึงหรือลบข้อมูลได้
ตัวอย่างที่อันตราย: ถ้าผู้ใช้กรอก `105 OR 1=1` ระบบจะได้ Query ที่ดึงข้อมูลทุกแถว
```sql
SELECT * FROM Users WHERE UserId = 105 OR 1=1;
```
วิธีป้องกัน: ใช้ Parameterized Query หรือ Prepared Statement เสมอ
```csharp
// C# / ASP.NET
var cmd = new SqlCommand("SELECT * FROM Users WHERE UserId = @id", conn);
cmd.Parameters.AddWithValue("@id", txtUserId.Text);
```
```sql
-- MySQL Prepared Statement
PREPARE stmt FROM 'SELECT * FROM Users WHERE UserId = ?';
SET @id = 105;
EXECUTE stmt USING @id;
